import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`website-clone-brief`,heroTitle:`Clone any website in minutes`,heroSubtitle:`Perplexity Computer analyzes your inspiration site, reverse-engineers its layout, copy, and design system, and rebuilds it for you — automatically.`,inputUrlCta:`Clone this site`,inputUrlPlaceholder:`competitor-site.com`,inputUrlPrefill:`Go to {url} and perform a complete website teardown and rebuild. 1) Analyze every major page and document the full page-by-page layout logic — hero sections, content blocks, grid structures, and component hierarchy. 2) Extract copy patterns and headline formulas — analyze the tone, messaging framework, CTAs, and persuasion techniques used across the site. 3) Map the navigation and information architecture — sitemap structure, menu hierarchy, internal linking patterns, and user flow logic. 4) Document the design system — fonts, color palette with hex codes, spacing conventions, button styles, icon usage, imagery approach, and responsive breakpoints. 5) Trace the full conversion flow from landing page to final CTA — every step, form, trust signal, and micro-interaction. 6) Using all of this, rebuild the site as a fully functional web app deployed to a live URL — with the same layout logic, navigation structure, and design system, but with placeholder content ready for me to customize. Include a reference panel that shows the original site's design system notes alongside the rebuild.`,heroOverlaySteps:[`Analyzing every page for layout, copy, and design patterns`,`Mapping navigation architecture and conversion flows`,`Extracting the full design system — fonts, colors, spacing`,`Site rebuilt and deployed to a live URL — ready to customize`],generatingSteps:[`Visiting {url} to analyze page layouts, copy patterns, and design elements`,`Designing an agent to reverse-engineer the site's architecture, design system, and conversion flow`,`Configuring page-by-page rebuild with matching layout logic and component structure`,`Setting up live deployment with design system reference panel`],featureSectionTitle:`From inspiration URL to working site`,featureCardTitles:[`Connects to your dev stack`,`Outputs you can ship`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`GitHub, Figma, Notion, Google Drive, Slack — Computer pushes your rebuilt site, design tokens, and documentation straight into the tools your team uses.`,`Live rebuilt site. Page-by-page layout specs. Full design system with hex codes, fonts, and spacing. Navigation sitemap. Conversion flow teardown. Copy pattern playbook.`],capabilitySectionTitle:`Your product team, on autopilot`,capabilitySectionSubtitle:`Paste a URL, step away, come back to a fully rebuilt site.`,capabilityCards:[{title:`Full Site Analysis`,description:`Computer can analyze every page of an inspiration site — documenting layout logic, component hierarchy, and content block structure page by page.`},{title:`Copy Teardown`,description:`Computer can extract headline formulas, messaging frameworks, CTA patterns, and persuasion techniques — so you know exactly why the copy works.`},{title:`Design System Extraction`,description:`Computer can pull fonts, color palettes, spacing rules, button styles, and responsive breakpoints — delivered as a reusable design reference.`},{title:`Connect Your Tools`,description:`Computer can push code to GitHub, sync specs to Figma and Notion, and notify your team in Slack — build workflows across your entire product stack.`},{title:`Remember & Iterate`,description:`Computer can remember past site clones, your brand preferences, and design decisions — so every rebuild gets closer to your ideal output.`},{title:`Monitor & Alert`,description:`Computer can re-analyze inspiration sites on a schedule and flag when they update layouts, redesign pages, or change conversion flows.`}]});export{t as default};
